	}
	if strings.Contains(f.View(), curlyUnderline) || footerStatus(f).Text != "" {
		t.Error("unticking the invalid port left the error in place")
	}
}

func TestLaunchFormAdditionalPortsAndEnvironmentAreNeverRefused(t *testing.T) {
