		t.Errorf("formStatus().Text = %q after the correction, want empty", st.Text)
	}
	if _, ok := submitLaunch(f); !ok {
		t.Error("submit refused after the correction")
	}
}

func TestLaunchFormErrorFollowsAnEditAfterARefusal(t *testing.T) {
