	setHostPort(f, 0, "80", true)
	setHostPort(f, 1, "", true)
	f, _ = submitLaunch(f) // accepted: nothing armed yet beyond a clean submit
	setHostPort(f, 0, "80a0", true)
	f.ports[0].hostPortInput.SetValue("0")
	f, submitted := submitLaunch(f)
	if submitted {
